def solve(nested):
    """Flatten arbitrarily nested lists (and tuple-like containers) in order."""
    stack = [nested]
    out = []
    while stack:
        cur = stack.pop()
        if isinstance(cur, (list, tuple)):
            stack.extend(reversed(cur))
        elif isinstance(cur, (str, bytes)):
            out.append(cur)
        else:
            try:
                items = list(iter(cur))
