def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    The grid may be empty or have rows of varying lengths (jagged). Cells are
    4-directionally connected (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # Check bounds: row must exist and column index within that row
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

