def solve(grid):
    """Count islands in a grid where cells contain 0/1 (int or string) or boolean.
    Handles empty grid and jagged rows. 4-directional connectivity.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds checks
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            cell = grid[i][j]
            # consider as land if cell is 1, '1', or True
            if cell not in (1, '1', True):
                continue
            visited.add((i, j))
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            cell = grid[i][j]
            if cell in (1, '1', True) and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

