def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[i]) for i in range(rows) ]
    def is_land(val):
        # consider as land if val represents 1
        if isinstance(val, bool):
            return val is True
        try:
            return int(val) == 1
        except Exception:
            return False
    def dfs(r,c):
        stack=[(r,c)]
        while stack:
            i,j=stack.pop()
            if i<0 or i>=rows or j<0 or j>=len(grid[i]):
                continue
            if visited[i][j]:
                continue
            if not is_land(grid[i][j]):
                continue
            visited[i][j]=True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count=0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and is_land(grid[i][j]):
                dfs(i,j)
                count+=1
    return count

