def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a two‑element list/tuple [start, end]. Intervals where start > end are ignored.
    Meetings may touch at endpoints (start == previous end is allowed).
    """
    intervals = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        s, e = m[0], m[1]
        # Ensure numeric and comparable; skip if not
        try:
            if s > e:
                continue
        except Exception:
            continue
        intervals.append((s, e))
    # Sort by end time, then by start time to handle ties correctly
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in intervals:
        if s >= current_end:
            count += 1
