def solve(path):
    """Simplify a Unix absolute path.
    Args:
        path (str): absolute path starting with '/'.
    Returns:
        str: canonical path.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
