def solve(grid):
    """Count islands in a binary grid.
    Works for non-rectangular grids and empty input.
    """
    if not grid:
        return 0
    m = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # neighbors (up, down, left, right) if within bounds and value == 1
            for di, dj in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < len(grid[ni]) and (ni, nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(m):
        row_len = len(grid[i])
        for j in range(row_len):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

