def solve(meetings):
    intervals = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        s, e = m[0], m[1]
        # try to compare
        try:
            # swap if needed
            if s > e:
                s, e = e, s
        except Exception:
            continue
        intervals.append((s, e))
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    cur_end = -float('inf')
    for s, e in intervals:
        if s >= cur_end:
            count += 1
            cur_end = e
