def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of adjacent cells with value 1 (up, down, left, right).
    The function does **not** modify the input grid.
    """
    if not grid:
        return 0
    m = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore four neighbours
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1:
                    if (ni, nj) not in visited:
                        stack.append((ni, nj))
    count = 0
    for i in range(m):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

