def solve(grid):
    """Count islands (connected components of 1) in a possibly jagged grid.
    A cell is considered land if it evaluates to integer 1 (e.g., 1, '1', 1.0, True).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(val):
        try:
            return int(val) == 1
        except Exception:
            return False
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if not is_land(grid[i][j]):
                continue
            visited.add((i, j))
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if is_land(grid[i][j]) and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

