def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    Handles non‑int inputs by converting to int when possible; negative or
    non‑numeric values yield 0. Uses a straightforward Sieve of Eratosthenes.
    """
    # Convert to int if possible
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n‑1
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(sieve)

