def solve(mat):
    n = len(mat)
    if n == 0:
        return 1
    if n == 1:
        return mat[0][0]
    # Use Bareiss algorithm for exact integer determinant
    A = [row[:] for row in mat]
    det_sign = 1
    for k in range(n-1):
        # pivot if zero
        if A[k][k] == 0:
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
        pivot = A[k][k]
        if pivot == 0:
            return 0
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j])
                if k > 0:
                    A[i][j] //= A[k-1][k-1]
            A[i][k] = 0
    return det_sign * A[n-1][n-1]

