def solve(s):
    """Convert a Roman numeral to an integer.
    Handles empty string (returns 0) and case-insensitive input.
    """
    if not s:
        return 0
    s = s.upper()
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
              'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i + 1 < n and values[s[i]] < values[s[i + 1]]:
            total += values[s[i + 1]] - values[s[i]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total

